package com.example.ui.screens

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.util.Base64

/**
 * Chapter figures embedded as base64 JPEG data, so the Read tab can display
 * them without drawable resources. Keys match chapterSectionFigures().
 * Generated from the chapter PNG artwork; do not edit by hand.
 */
object ChapterFigureData {

    fun decode(key: String): Bitmap? {
        val b64 = images[key] ?: return null
        return try {
            val bytes = Base64.decode(b64, Base64.DEFAULT)
            BitmapFactory.decodeByteArray(bytes, 0, bytes.size)
        } catch (e: Exception) {
            null
        }
    }

